create table public.connections(user_low_id uuid not null references public.profiles(id) on delete cascade,user_high_id uuid not null references public.profiles(id) on delete cascade,requested_by uuid not null references public.profiles(id) on delete restrict,status text not null default 'pending',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),primary key(user_low_id,user_high_id),constraint connection_order check(user_low_id<user_high_id),constraint connection_requester check(requested_by in(user_low_id,user_high_id)));
create table public.conversations(id uuid primary key default gen_random_uuid(),conversation_type text not null,creator_id uuid references public.profiles(id) on delete set null,title text,last_message_at timestamptz,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table public.conversation_members(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,member_role text not null default 'member',joined_at timestamptz not null default timezone('utc',now()),left_at timestamptz,last_read_at timestamptz,muted boolean not null default false,primary key(conversation_id,user_id));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete restrict,sender_id uuid not null references public.profiles(id) on delete restrict,body text not null default '',message_type text not null default 'text',reply_to_id uuid references public.messages(id) on delete set null,created_at timestamptz not null default timezone('utc',now()),edited_at timestamptz,deleted_at timestamptz);
create table public.message_attachments(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,media_asset_id uuid not null references public.media_assets(id) on delete restrict,position smallint not null,created_at timestamptz not null default timezone('utc',now()),unique(message_id,position));
create table public.message_receipts(message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,delivered_at timestamptz,read_at timestamptz,primary key(message_id,user_id));
create index conversation_members_user_idx on public.conversation_members(user_id,left_at);create index messages_cursor_idx on public.messages(conversation_id,created_at desc,id desc);alter table public.connections enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;alter table public.message_attachments enable row level security;alter table public.message_receipts enable row level security;
create policy connections_participants on public.connections for select to authenticated using(auth.uid() in(user_low_id,user_high_id));create policy connections_insert on public.connections for insert to authenticated with check(requested_by=auth.uid() and auth.uid() in(user_low_id,user_high_id));create policy connections_update on public.connections for update to authenticated using(auth.uid() in(user_low_id,user_high_id)) with check(auth.uid() in(user_low_id,user_high_id));create policy conversations_read on public.conversations for select to authenticated using(exists(select 1 from public.conversation_members m where m.conversation_id=id and m.user_id=auth.uid() and m.left_at is null));create policy members_read on public.conversation_members for select to authenticated using(exists(select 1 from public.conversation_members m where m.conversation_id=conversation_id and m.user_id=auth.uid()));create policy messages_read on public.messages for select to authenticated using(exists(select 1 from public.conversation_members m where m.conversation_id=messages.conversation_id and m.user_id=auth.uid() and m.left_at is null));create policy messages_insert on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversation_members m where m.conversation_id=messages.conversation_id and m.user_id=auth.uid() and m.left_at is null));create policy messages_update on public.messages for update to authenticated using(sender_id=auth.uid()) with check(sender_id=auth.uid());create policy attachments_read on public.message_attachments for select to authenticated using(exists(select 1 from public.messages m join public.conversation_members cm on cm.conversation_id=m.conversation_id where m.id=message_id and cm.user_id=auth.uid()));create policy receipts_owner on public.message_receipts for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
